kIn = input(7, "k Neighbors", 1, 15, 1)
featLen = input(20, "Feature Bars", 5, 40, 1)
histLen = input(200, "History Bars", 50, 500, 10)
mThresh = input(0.43, "Margin Thresh", 0.05, 1.0, 0.01)
dThresh = input(0.35, "Disagree Thresh", 0.05, 1.0, 0.01)

kEff = 7
if kIn < 7 { kEff := kIn }
if kIn < 1 { kEff := 1 }

warm = bar_index >= histLen + featLen + 5

d0 = 999999.0
d1 = 999999.0
d2 = 999999.0
d3 = 999999.0
d4 = 999999.0
d5 = 999999.0
d6 = 999999.0
l0 = 0
l1 = 0
l2 = 0
l3 = 0
l4 = 0
l5 = 0
l6 = 0

i = 1
while i <= histLen {
    ssd = 0.0
    j = 0
    while j < featLen {
        a1 = close[j] - close[j + 1]
        b1 = close[j + 1] + 0.000000001
        c0 = a1 / b1
        a2 = close[i + j] - close[i + j + 1]
        b2 = close[i + j + 1] + 0.000000001
        ci = a2 / b2
        diff = c0 - ci
        ssd := ssd + diff * diff
        j := j + 1
    }
    dist = sqrt(ssd)
    lbl = 0 - 1
    if close[i - 1] > close[i] { lbl := 1 }
    if dist < d0 {
        d6 := d5
        l6 := l5
        d5 := d4
        l5 := l4
        d4 := d3
        l4 := l3
        d3 := d2
        l3 := l2
        d2 := d1
        l2 := l1
        d1 := d0
        l1 := l0
        d0 := dist
        l0 := lbl
    } else {
        if dist < d1 {
            d6 := d5
            l6 := l5
            d5 := d4
            l5 := l4
            d4 := d3
            l4 := l3
            d3 := d2
            l3 := l2
            d2 := d1
            l2 := l1
            d1 := dist
            l1 := lbl
        } else {
            if dist < d2 {
                d6 := d5
                l6 := l5
                d5 := d4
                l5 := l4
                d4 := d3
                l4 := l3
                d3 := d2
                l3 := l2
                d2 := dist
                l2 := lbl
            } else {
                if dist < d3 {
                    d6 := d5
                    l6 := l5
                    d5 := d4
                    l5 := l4
                    d4 := d3
                    l4 := l3
                    d3 := dist
                    l3 := lbl
                } else {
                    if dist < d4 {
                        d6 := d5
                        l6 := l5
                        d5 := d4
                        l5 := l4
                        d4 := dist
                        l4 := lbl
                    } else {
                        if dist < d5 {
                            d6 := d5
                            l6 := l5
                            d5 := dist
                            l5 := lbl
                        } else {
                            if dist < d6 {
                                d6 := dist
                                l6 := lbl
                            }
                        }
                    }
                }
            }
        }
    }
    i := i + 1
}

upCount = 0
downCount = 0
if kEff >= 1 {
    if l0 == 1 { upCount := upCount + 1 } else { downCount := downCount + 1 }
}
if kEff >= 2 {
    if l1 == 1 { upCount := upCount + 1 } else { downCount := downCount + 1 }
}
if kEff >= 3 {
    if l2 == 1 { upCount := upCount + 1 } else { downCount := downCount + 1 }
}
if kEff >= 4 {
    if l3 == 1 { upCount := upCount + 1 } else { downCount := downCount + 1 }
}
if kEff >= 5 {
    if l4 == 1 { upCount := upCount + 1 } else { downCount := downCount + 1 }
}
if kEff >= 6 {
    if l5 == 1 { upCount := upCount + 1 } else { downCount := downCount + 1 }
}
if kEff >= 7 {
    if l6 == 1 { upCount := upCount + 1 } else { downCount := downCount + 1 }
}

margin = 0.0
if kEff > 0 { margin := (upCount - downCount) / kEff }
strength = abs(margin)

sumD = d0 + d1 + d2 + d3 + d4 + d5 + d6
useN = kEff
if useN < 1 { useN := 1 }
meanD = sumD / 7
if kEff < 7 { meanD := (d0 + d1 + d2 + d3 + d4 + d5 + d6) / 7 }
v0 = (d0 - meanD) * (d0 - meanD)
v1 = (d1 - meanD) * (d1 - meanD)
v2 = (d2 - meanD) * (d2 - meanD)
v3 = (d3 - meanD) * (d3 - meanD)
v4 = (d4 - meanD) * (d4 - meanD)
v5 = (d5 - meanD) * (d5 - meanD)
v6 = (d6 - meanD) * (d6 - meanD)
varD = (v0 + v1 + v2 + v3 + v4 + v5 + v6) / 7
stdevD = sqrt(varD)
cvRaw = stdevD / (meanD + 0.00001)
disagreeNorm = cvRaw
if disagreeNorm > 1.0 { disagreeNorm := 1.0 }
if disagreeNorm < 0.0 { disagreeNorm := 0.0 }
if warm == false { disagreeNorm := 1.0 }
if warm == false { margin := 0.0 }
if warm == false { strength := 0.0 }

buyCond = warm and margin > mThresh and disagreeNorm < dThresh
sellCond = warm and margin < 0 - mThresh and disagreeNorm < dThresh

var lastSig = 0
sigNow = 0
if buyCond { sigNow := 1 }
if sellCond { sigNow := 0 - 1 }

buySig = buyCond and lastSig <= 0
sellSig = sellCond and lastSig >= 0
if sigNow != 0 { lastSig := sigNow }

if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }

if buyCond { bgcolor("rgba(34,204,136,0.08)") }
if sellCond { bgcolor("rgba(255,68,119,0.08)") }

plot(margin, "Vote Margin M", "#b48cff", 2)
plot(disagreeNorm, "Disagreement D", "#ffd43b", 1)
plot(mThresh, "Margin +Thresh", "#22cc88", 1, "stepline")
plot(0 - mThresh, "Margin -Thresh", "#ff4477", 1, "stepline")
plot(dThresh, "Disagree Thresh", "#ffd43b", 1, "stepline")

plot3d(margin, "Vote Margin Spine", "ribbon", "#b48cff", "separate")
plot3d(disagreeNorm, "Disagreement Footprint", "bars3d", "#ffd43b", "separate", 1)

// Volume Session Value Model
// Volume-profile-on-chart: POC + value area from visible session, price leaving value is the signal.

rows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
sessLen = input(60, "Session Length Bars", 20, 200, 5)
show3D = input(true, "Show 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range ─────────────────────────────
hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 { rng := close * 0.01 }
binH = rng / rows

// ─── Bin volumes: sum volume where typical falls in bin ─
binVol = array()
b = 0
while b < rows {
    array.push(binVol, 0.0)
    b := b + 1
}
k = 0
while k < sessLen {
    tp = (high[k] + low[k] + close[k]) / 3
    bi = floor((tp - ll) / rng * rows)
    if bi < 0 { bi := 0 }
    if bi > rows - 1 { bi := rows - 1 }
    array.set(binVol, bi, array.get(binVol, bi) + volume[k])
    k := k + 1
}

// ─── Point of control ───────────────────────────────────
pocBin = 0
pocVol = array.get(binVol, 0)
i = 1
while i < rows {
    v = array.get(binVol, i)
    if v > pocVol {
        pocVol := v
        pocBin := i
    }
    i := i + 1
}
totalVol = array.sum(binVol)
pocShare = 0.0
if totalVol > 0 { pocShare := pocVol / totalVol }
pocPrice = ll + (pocBin + 0.5) / rows * rng

// ─── Value area: expand from POC ────────────────────────
vaLow = pocBin
vaHigh = pocBin
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < rows {
    leftVal = 0 - 1.0
    if vaLow > 0 { leftVal := array.get(binVol, vaLow - 1) }
    rightVal = 0 - 1.0
    if vaHigh < rows - 1 { rightVal := array.get(binVol, vaHigh + 1) }
    if rightVal >= leftVal and vaHigh < rows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) / rows * rng
valPrice = ll + vaLow / rows * rng
vaMid = (vahPrice + valPrice) / 2
terrainPrice = ll + pocShare * rng * 3
if terrainPrice > hh { terrainPrice := hh }
if terrainPrice < ll { terrainPrice := ll }

// ─── Signals: price leaving value ───────────────────────
buySig = close[1] <= vahPrice and close > vahPrice
sellSig = close[1] >= valPrice and close < valPrice
insideVA = close >= valPrice and close <= vahPrice
coneSz = 0.6 + pocShare * 8
if coneSz < 0.6 { coneSz := 0.6 }
if coneSz > 2.2 { coneSz := 2.2 }
coneSz := coneSz * markerSize

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    model.longEntry("VolValLong")
    model.exit("VolValExit")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    model.shortEntry("VolValShort")
    model.exit("VolValExit")
}
if buySig and show3D { plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", coneSz, "3d") }
if sellSig and show3D { plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", coneSz, "3d") }
if show3D { label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d") }

// ─── 2D profile histogram on right side of session ──────
maxBin = pocVol
if maxBin <= 0 { maxBin := 1 }
j = 0
while j < rows {
    bv = array.get(binVol, j)
    binBot = ll + j / rows * rng
    binTop = ll + (j + 1) / rows * rng
    ext = bv / maxBin * 10
    inVA = j >= vaLow and j <= vaHigh
    bc = "rgba(255,68,119,0.35)"
    bg = "rgba(255,68,119,0.10)"
    if inVA {
        bc := "#22cc88"
        bg := "rgba(34,204,136,0.25)"
    }
    if j == pocBin {
        bc := "#ffd43b"
        bg := "rgba(255,212,59,0.30)"
    }
    box.new(bar_index + 1, binTop, bar_index + 1 + ext, binBot, bc, bg, 1, "VPBIN")
    j := j + 1
}

// ─── 2D twins (carry same info when 3D is off) ──────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(close, "Close", "#ffffff", 1)

// ─── 3D terrain: value sits as terrain, POC as rail ─────
plot3d(terrainPrice, "Value Terrain", "ridgeline", "#22cc88", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH", "line3d", "#22cc88", "3d", 2)

